
-- ============================================
-- GlobalOnlineVisaApplications
-- Supabase Database Setup
-- ============================================

-- 1. Customer profiles and administrator roles
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    role TEXT NOT NULL DEFAULT 'customer'
        CHECK (role IN ('customer', 'admin')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. Visa applications
CREATE TABLE IF NOT EXISTS public.applications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name TEXT NOT NULL,
    email TEXT NOT NULL,
    phone TEXT NOT NULL,
    residence_country TEXT NOT NULL,
    destination_country TEXT NOT NULL,
    visa_type TEXT NOT NULL,
    travel_date DATE,
    message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Contact messages
CREATE TABLE IF NOT EXISTS public.contact_messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    subject TEXT NOT NULL,
    message TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Enable Row Level Security
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;

-- 5. Profiles: users can read their own profile
CREATE POLICY "Users can read their own profile"
ON public.profiles
FOR SELECT
TO authenticated
USING (id = (SELECT auth.uid()));

-- 6. Customers can submit visa applications
CREATE POLICY "Public can submit applications"
ON public.applications
FOR INSERT
TO anon, authenticated
WITH CHECK (true);

-- 7. Only administrators can read applications
CREATE POLICY "Admins can read applications"
ON public.applications
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1
        FROM public.profiles
        WHERE profiles.id = (SELECT auth.uid())
        AND profiles.role = 'admin'
    )
);

-- 8. Visitors can submit contact messages
CREATE POLICY "Public can submit contact messages"
ON public.contact_messages
FOR INSERT
TO anon, authenticated
WITH CHECK (true);

-- 9. Only administrators can read contact messages
CREATE POLICY "Admins can read contact messages"
ON public.contact_messages
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1
        FROM public.profiles
        WHERE profiles.id = (SELECT auth.uid())
        AND profiles.role = 'admin'
    )
);

-- ============================================
-- IMPORTANT ADMIN SETUP
-- ============================================
-- After creating your administrator account in
-- Supabase Authentication, copy its user UUID.
--
-- Then run this separately in the SQL Editor,
-- replacing the example UUID:
--
-- INSERT INTO public.profiles (id, role)
-- VALUES ('YOUR-AUTH-USER-UUID', 'admin');
--
-- Do not give public users permission to create
-- or change administrator profiles.
-- ============================================
